class BubbleSort {

   int[] zahlen = new int[10];
   GUI gui; 

   BubbleSort() {


      // Mit Zufallszahlen belegen
      for (int i = 0; i < zahlen.length; i++) {
         zahlen[i] = Random.randint(1, 100);
      }

      // Zahlen ausgeben
      for (int i = 0; i < zahlen.length; i++) {
         print(zahlen[i] + " ");
      }
      println();
      gui = new GUI(this); 
   }

   void sort() {
      boolean fertig = false;
      // TODO BubbleSort umsetzen
      while (!fertig) {
         fertig = true;
         // Sortieren!
         // i zeigt auf die linke zu überprüfende Zahl
         for (int i = 0; i < zahlen.length - 1; i++) {
            gui.recolor(i);
            // Wenn links größer als rechts
            if(zahlen[i] > zahlen[i + 1]) {
               // dann tauschen und noch nicht fertig
               fertig = false;
               int z = zahlen[i];
               zahlen[i] = zahlen[i + 1];
               zahlen[i + 1] = z;
               gui.swap(i);
            } 
            gui.decolor(i);
         }
      }

      // Sortiertes Array ausgeben
      println();
      for (int i = 0; i < zahlen.length; i++) {
         print(zahlen[i] + " ");
      }

      println();
      println("Done");
      System.exit(1);
   }

   void sortOptimised() {
      boolean fertig = false;
      int last = zahlen.length - 1;
      // TODO BubbleSort umsetzen
      while (!fertig) {
         fertig = true;
         // Sortieren!
         // i zeigt auf die linke zu überprüfende Zahl
         for (int i = 0; i < last; i++) {
            gui.recolor(i);
            // Wenn links größer als rechts
            if(zahlen[i] > zahlen[i + 1]) {
               // dann tauschen und noch nicht fertig
               fertig = false;
               int z = zahlen[i];
               zahlen[i] = zahlen[i + 1];
               zahlen[i + 1] = z;
               gui.swap(i);
            } 
            gui.decolor(i);
         }
         last--;
      }

      // Sortiertes Array ausgeben
      println();
      for (int i = 0; i < zahlen.length; i++) {
         print(zahlen[i] + " ");
      }

      println();
      println("Done");
      System.exit(1);
   }

}

new World(600, 800);
BubbleSort b = new BubbleSort(); 
b.sortOptimised();

class GUI extends Actor {

   private BubbleSort sort;

   private ArrayList<Rectangle> bars = new ArrayList<>();

   private final static int PADDING_TOP = 100;
   private final static int PADDING_LEFT = 100;

   private final int SPACE_BETWEEN_BAR = 15;
   private final static int BAR_WIDTH = 25; 
   private final static int BAR_HEIGHT_SKALAR = 5;

   private final static String BAR_COLOR = "blue";
   private final static String BAR_COLOR_SMALLER = "orange";
   private final static String BAR_COLOR_LARGER = "purple";

   public GUI(BubbleSort _sort) {
      this.sort = _sort;
      createBars();
   }

   private void createBars() {
      for (int i = 0; i < sort.zahlen.length; i++) {
         Rectangle r = new Rectangle(PADDING_LEFT + i * SPACE_BETWEEN_BAR + i * BAR_WIDTH, PADDING_TOP, BAR_WIDTH, BAR_HEIGHT_SKALAR * sort.zahlen[i]);
         r.setFillColor(BAR_COLOR);
         SystemTools.pause(100);
         bars.add(r);
      }
   }

   void clear() {
      for (Rectangle r : bars) {
         r.destroy();
      }
   }

   void recolor(int i) {
      bars.get(i).setFillColor(BAR_COLOR_LARGER);
      bars.get(i + 1).setFillColor(BAR_COLOR_SMALLER);
      SystemTools.pause(200);
   }

   void decolor(int i) {
      bars.get(i).setFillColor(BAR_COLOR);
      bars.get(i + 1).setFillColor(BAR_COLOR);
      SystemTools.pause(200);
   }

   void swap(int i) {
      Rectangle r1 = bars.get(i);
      r1.moveTo(PADDING_LEFT + (i + 1) * SPACE_BETWEEN_BAR + (i + 1) * BAR_WIDTH, PADDING_TOP);
      SystemTools.pause(100);

      Rectangle r2 = bars.get(i + 1);
      r2.moveTo(PADDING_LEFT + i * SPACE_BETWEEN_BAR + i * BAR_WIDTH, PADDING_TOP);

      SystemTools.pause(200);
      bars.set(i, r2);
      bars.set(i + 1, r1);
      r1.setFillColor(BAR_COLOR);
      r2.setFillColor(BAR_COLOR);
   }

   void fullRepaint() {
      clear();
      createBars();
   }
}
